#[cfg(test)]
mod tests {
    use crate::test_util::parse;

    fn dump(source: &str) {
        let tree = parse(source);
        println!("=== {source:?} ===");
        let mut cursor = tree.root_node().walk();
        fn walk(node: tree_sitter::Node, depth: usize, cursor: &mut tree_sitter::TreeCursor, src: &str) {
            let txt: String = src[node.start_byte()..node.end_byte()].chars().take(40).collect();
            println!(
                "{}{} [{}-{}] {:?}",
                "  ".repeat(depth),
                node.kind(),
                node.start_byte(),
                node.end_byte(),
                txt.replace('\n', "\\n")
            );
            if cursor.goto_first_child() {
                loop {
                    walk(cursor.node(), depth + 1, cursor, src);
                    if !cursor.goto_next_sibling() {
                        break;
                    }
                }
                cursor.goto_parent();
            }
        }
        walk(tree.root_node(), 0, &mut cursor, source);
    }

    #[test]
    fn dump_trees() {
        dump("f = fixpoint('fixpoint', 'xpc');\n");
        dump("slrt 'slrt' 'powersys'\n");
        dump("x = 'distcomp';\n");
        dump("disp('simevents')\n");
        dump("hh = hrn('North America', 'Western Europe');\n");
        dump("save('file.mat', 'v6');\n");
        dump("print('-dill', 'file.eps');\n");
        dump("print -adobecset file.eps\n");
        dump("figure('Renderer', 'painters');\n");
        dump("set(gcf, 'RendererMode', 'manual');\n");
        dump("get(gcf, 'Renderer');\n");
        dump("plot(x, 'Renderer', y);\n");
        dump("schema.prop('MyClass', 'prop', 'double');\n");
        dump("schema('foo');\n");
        dump("schemaType('bar');\n");
        dump("x = schema;\n");
        dump("classdef C\n  properties\n    x @double\n  end\nend\n");
        dump("f = @(x) x + 1;\n");
        dump("g = @double;\n");
        dump("h = @foo.bar;\n");
        dump("function y = f(x @double)\ny = x;\nend\n");
        dump("function y = f(x)\n  arguments\n    x @double\n  end\n  y = x;\nend\n");
        dump("addpath('C:/myproj/resources');\n");
        dump("addpath(fullfile('resources', 'sub'));\n");
        dump("cd resources\n");
        dump("import mypkg.resources.helper;\n");
        dump("x = 'resources';\n");
    }
}

